import { cn, Slot } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { LabelHTMLAttributes, ReactNode } from 'react'
import styles from './label.module.css'

export interface LabelProps extends LabelHTMLAttributes<HTMLLabelElement> {
  /**
   * When true, renders the child element as the root via Slot, merging props (polymorphic
   * rendering).
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  asChild?: boolean
  /**
   * When true, marks the field as required.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  required?: boolean
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  children: ReactNode
  /** Override built-in strings (e.g. the required-marker accessible text). */
  labels?: { required?: string }
}

export function Label({
  asChild = false,
  required = false,
  disabled = false,
  className,
  children,
  labels,
  ...props
}: LabelProps) {
  const Comp = asChild ? Slot : 'label'
  const requiredText = labels?.required ?? t(builtin.label.required)

  const marker = required ? (
    <>
      <span className={styles['marker']} aria-hidden="true">
        *
      </span>
      <span className={styles['srOnly']}>{requiredText}</span>
    </>
  ) : null

  return (
    <Comp
      data-disabled={disabled ? '' : undefined}
      className={cn(styles['label'], className as string | undefined)}
      {...(props as Record<string, unknown>)}
    >
      {marker ? (
        <>
          {children}
          {marker}
        </>
      ) : (
        children
      )}
    </Comp>
  )
}

@layer cascivo.component {
  .label {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    line-height: var(--cascivo-leading-snug);
    color: var(--cascivo-color-text);

    &[data-disabled] {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  .marker {
    color: var(--cascivo-color-destructive);
    line-height: var(--cascivo-leading-none);
  }

  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    overflow: hidden;
    white-space: nowrap;
  }
}

@media (forced-colors: active) {
  .label[data-disabled] {
    color: GrayText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Label',
  description: 'Accessible caption for a form control',
  category: 'inputs',
  clientJs: 'none',
  states: ['default', 'disabled'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'htmlFor',
      description: 'Id of the form control this label is associated with.',
      type: 'string',
