      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'children',
      description: 'Content rendered inside the component.',
      type: 'ReactNode',
      required: true,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ required?: string }',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-space-1',
    '--cascivo-font-sans',
    '--cascivo-text-sm',
    '--cascivo-font-medium',
    '--cascivo-leading-snug',
    '--cascivo-leading-none',
    '--cascivo-color-text',
    '--cascivo-color-destructive',
  ],
  accessibility: {
    role: 'label',
    wcag: '2.2-AA',
    keyboard: [],
    forcedColors: true,
  },
  examples: [
    { title: 'Basic', code: '<Label htmlFor="email">Email</Label>' },
    { title: 'Required', code: '<Label htmlFor="email" required>Email</Label>' },
    {
      title: 'asChild',
      code: '<Label asChild htmlFor="email"><span>Email</span></Label>',
      description: 'Render the label semantics onto a custom element via Slot.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['form', 'caption', 'accessibility'],
  intent: {
    whenToUse: [
      'Naming a single form control (input, select, checkbox) so clicking the text focuses it',
      'Marking a field as required with a visible and screen-reader-announced indicator',
    ],
    whenNotToUse: [
      'Labeling a group of controls — use a <fieldset>/<legend> instead',
      'Static body copy that is not associated with a control — use a plain text element',
    ],
    antiPatterns: [
      {
        bad: '<Label>Email</Label><input id="email" />',
        good: '<Label htmlFor="email">Email</Label><input id="email" />',
        why: 'Without htmlFor the label is not programmatically associated, so click-to-focus and screen-reader naming break',
      },
      {
        bad: '<Label required>Email <span>*</span></Label>',
        good: '<Label required>Email</Label>',
        why: 'The required marker is rendered for you with an accessible text alternative; a hand-added asterisk is silent to screen readers',
      },
    ],
    related: [
      {
        name: 'Field',
        relationship: 'contained-by',
        reason:
          'Field composes Label with a control, description, and error and wires the ids automatically',
      },
      {
