        relationship: 'pairs-with',
        reason: 'A label names the input it points at via htmlFor',
      },
    ],
    a11yRationale:
      'Renders a native <label> so the platform handles click-to-focus and accessible naming; the required marker pairs an aria-hidden asterisk with visually-hidden localized text so the requirement is both seen and announced',
    content: {
      // Children are the page's authored prose, not chrome this component owns —
      // so `audit --ai`'s raw-string rule must not flag every sentence.
      contentPrimitive: true,
      tone: 'Short noun phrase naming the field',
      notes: 'Sentence case, no trailing colon; let the required marker convey requirement',
    },
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Colors and type must resolve to --cascivo-* semantic tokens',
      },
      { area: 'label copy', level: 'flexible', note: 'Free, within tone guidance' },
    ],
  },
}
